const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const mapCanvas=document.getElementById('map'),mctx=mapCanvas.getContext('2d');
let W,H,dpr;let keys={},mouse={x:0,y:0,down:false};let running=false,last=0,startedAt=0,shake=0,muted=false;
const player={x:0,y:0,r:14,angle:0,hp:100,shield:50,speed:190,fireCd:0,dashCd:0,novaCd:0,inv:0};
let enemies=[],bolts=[],enemyBolts=[],pickups=[],particles=[],zone={x:0,y:0,r:430,tx:0,ty:0,tr:430},elims=0,relics=0,gameOver=false,fallen=[],parallax=0;
const $=id=>document.getElementById(id);
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W*.58;player.y=H*.58}}addEventListener('resize',resize);resize();
function rand(a,b){return a+Math.random*(b-a)}
function dist(a,b,c,d){return Math.hypot(a-c,b-d)}
function reset(){running=true;gameOver=false;elims=0;relics=0;pickups=[];enemies=[];bolts=[];enemyBolts=[];particles=[];fallen=[];player.x=W*.58;player.y=H*.58;player.hp=100;player.shield=50;player.fireCd=0;player.dashCd=0;player.novaCd=0;player.inv=0;zone.r=Math.min(W,H)*.7;zone.tr=zone.r;zone.x=W*.5;zone.y=H*.5;startedAt=performance.now();for(let i=0;i<14;i++)spawnEnemy();for(let i=0;i<6;i++)spawnPickup();$('aliveCount').textContent='48';$('elimCount').textContent='00';$('endOverlay').classList.add('hidden');$('centerMessage').innerHTML='ISLAND UNLOCKED<span>secure the glowing relics</span>';setTimeout(()=>{$('centerMessage').innerHTML=''},2200);updateUI()}
function spawnEnemy(){let a=Math.random()*Math.PI*2,r=rand(Math.min(W,H)*.3,Math.min(W,H)*.48);let ex=zone.x+Math.cos(a)*r,ey=zone.y+Math.sin(a)*r;enemies.push({x:ex,y:ey,r:12,hp:rand(20,38),angle:0,cool:rand(.5,2),phase:Math.random()*6,speed:rand(24,48),flash:0,frozen:0})}
function spawnPickup(){let a=Math.random()*Math.PI*2,r=Math.random()*Math.min(W,H)*.35;pickups.push({x:zone.x+Math.cos(a)*r,y:zone.y+Math.sin(a)*r,r:9,type:Math.random()<.7?'relic':'med',spin:Math.random()*6})}
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='r')reset();if(e.key.toLower){}if(e.key.toLowerCase()==='q')nova();if(e.key==='Shift')dash()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);canvas.addEventListener('mousemove',e=>{let r=canvas.getBoundingRect?.()||canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top});canvas.addEventListener('mousedown',()=>mouse.down=true);addEventListener('mouseup',()=>mouse.down=false);
canvas.addEventListener('touchmove',e=>{e.preventEvent;let t=e.touches[0],r=canvas.getBoundingClientRect();mouse.x=t.clientX-r.left;mouse.y=t.clientY-r.top},{passive:false});
$('playBtn').onclick=$('guidePlay').onclick=$('skipBtn').onclick=()=>{$('startOverlay').classList.add('closed');$('howModal').classList.add('hidden');reset()};$('howBtn').onclick=()=>$('howModal').classList.remove('hidden');$('modalClose').onclick=()=>$('howModal').classList.add('hidden');$('againBtn').onclick=reset;$('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').textContent=muted?'×':'♫'};
function dash(){if(!running||player.dashCd>0)return;let dx=(keys.d?'1':0)-(keys.a?'1':0),dy=(keys.s?'1':0)-(keys.w?'1':0);let l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;player.x+=dx*115;player.y+=dy*115;player.inv=0.25;player.dashCd=3;burst(player.x,player.y,'#79dfff',14)}
function nova(){if(!running||player.novaCd>0)return;player.novaCd=12;burst(player.x,player.y,'#9beaff',28);shake=8;for(let e of enemies)if(dist(player.x,player.y,e.x,e.y)<155)e.frozen=3}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=Math.random()*180;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.35,.8),max:.8,color,size:rand(1,4)})}}
function shoot(){if(player.fireCd<=0){let a=player.angle,spd=620;bolts.push({x:player.x+Math.cos(a)*22,y:player.y+Math.sin(a)*22,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,life:1.4});player.fireCd=.16;burst(player.x+Math.cos(a)*24,player.y+Math.sin(a)*24,'#ffdc86',3)}}
function update(dt){if(!running)return;let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0),l=Math.hypot(dx,dy);if(l){dx/=l;dy/=l;player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt}player.x=Math.max(22,Math.min(W-22,player.x));player.y=Math.max(64,Math.min(H-22,player.y));player.angle=Math.atan2((mouse.y||H*.5)-player.y,(mouse.x||W*.5)-player.x);if(mouse.down||keys[' '] )shoot();player.fireCd-=dt;player.dashCd-=dt;player.novaCd-=dt;player.inv-=dt;if(player.novaCd<0)player.novaCd=0;if(player.dashCd<0)player.dashCd=0;$('novaReady').textContent=player.novaCd<=0?'READY':Math.ceil(player.novaCd)+'S';
for(let b of bolts){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt}bolts=bolts.filter(b=>b.life>0&&b.x>-30&&b.x<W+30&&b.y>-30&&b.y<H+30);
for(let e of enemies){e.flash-=dt;e.frozen-=dt;e.cool-=dt;e.phase+=dt;e.angle=Math.atan2(player.y-e.y,player.x-e.x);if(e.frozen<=0){let d=dist(e.x,e.y,player.x,player.y);if(d>210){e.x+=Math.cos(e.angle)*e.speed*dt;e.y+=Math.sin(e.angle)*e.speed*dt}else if(d<145&&e.cool<=0){enemyBolts.push({x:e.x,y:e.y,vx:Math.cos(e.angle)*270,vy:Math.sin(e.angle)*270,life:2});e.cool=rand(.8,1.8)}}} 
for(let b of bolts)for(let e of enemies)if(e.hp>0&&dist(b.x,b.y,e.x,e.y)<e.r+5){e.hp-=18;e.flash=.12;b.life=0;burst(e.x,e.y,'#ff9e83',5)}for(let i=enemies.length-1;i>=0;i--)if(enemies[i].hp<=0){let e=enemies[i];burst(e.x,e.y,'#be8cff',18);pickups.push({x:e.x,y:e.y,r:8,type:elims%3===0?'med':'relic',spin:0});enemies.splice(i,1);elims++;$('elimCount').textContent=String(elims).padStart(2,'0');$('aliveCount').textContent=String(Math.max(34-elims,1)).padStart(2,'0');if(enemies.length<7)spawnEnemy()}
for(let b of enemyBolts){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(player.inv<=0&&dist(b.x,b.y,player.x,player.y)<player.r+4)damage(12)}enemyBolts=enemyBolts.filter(b=>b.life>0);
for(let i=pickups.length-1;i>=0;i--){let p=pickups[i];p.spin+=dt;if(dist(p.x,p.y,player.x,player.y)<p.r+20){if(p.type==='relic'){relics++;toast('RELIC RECOVERED');if(relics>=3)zone.tr*=.72}else{player.hp=Math.min(100,player.hp+18);toast('VITALS RESTORED')}burst(p.x,p.y,p.type==='relic'?'#ffd776':'#76ffc1',12);pickups.splice(i,1)}}
let d=dist(player.x,player.y,zone.x,zone.y);if(d>zone.r&&player.inv<=0)damage(7*dt);zone.tr=Math.max(190,zone.tr-(dt*3));zone.r+=(zone.tr-zone.r)*dt*.5;zoneTimer(dt);
for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;p.life-=dt}particles=particles.filter(p=>p.life>0);shake*=.88;parallax+=dt*.12;updateUI();if(relics>=3&&enemies.length===0)endGame(true);if(player.hp<=0)endGame(false)}
function damage(n){if(player.shield>0){let used=Math.min(player.shield,n);player.shield-=used;n-=used}player.hp-=n;shake=6;burst(player.x,player.y,'#ff6f86',5);if(player.hp<0)player.hp=0}
function zoneTimer(dt){zoneTimer=zoneTimer||84;zoneTimer-=dt;if(zoneTimer<0){zoneTimer=84;zone.tr=Math.max(190,zone.tr*.82);toast('STORM SURGE — ZONE SHRINKING')}$('zoneTimer').textContent='STORM IN '+String(Math.floor(zoneTimer/60)).padStart(2,'0')+':'+String(Math.floor(zoneTimer%60)).padStart(2,'0')}
function updateUI(){$('healthValue').textContent=Math.ceil(player.hp);$('healthFill').style.width=Math.max(0,player.hp)+'%';$('shieldValue').textContent=Math.ceil(player.shield)+' SHIELD';$('shieldFill').style.width=player.shield*2+'%';$('questFill').style.width=Math.min(100,relics/3*100)+'%';$('questCount').textContent=relics+' / 3 relics';$('objectiveTitle').textContent=relics>=3?'Relics secured':'Find the Crown';$('objectiveText').textContent=relics>=3?'The Crown is waking. Hold the island!':'Recover the relic before the storm closes.'}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),1500)}
function endGame(win){if(gameOver)return;gameOver=true;running=false;$('endOverlay').classList.remove('hidden');$('endEyebrow').textContent=win?'VICTORY SECURED':'MATCH COMPLETE';$('endTitle').innerHTML=win?'CROWN<br><em>CLAIMED.</em>':'YOU WERE<br><em>DEFEATED.</em>';$('endText').textContent=win?'The island will remember your name.':'The storm closes, but legends rise again.';$('endElims').textContent=elims;$('endRelics').textContent=relics;let secs=Math.floor((performance.now()-startedAt)/1000);$('endTime').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')}
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function drawBackground(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#5a5e91');g.addColorStop(.42,'#6c8f9d');g.addColorStop(.75,'#476c69');g.addColorStop(1,'#263d45');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.save();ctx.globalAlpha=.45;ctx.fillStyle='#20254b';ctx.beginPath();ctx.moveTo(0,H*.54);for(let i=0;i<9;i++)ctx.lineTo(i*W/8,H*.39+Math.sin(i*1.7)*40);ctx.lineTo(W,H*.58);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();ctx.restore();drawCastle();drawTerrain();drawAtmosphere()}
function drawCastle(){let x=W*.50,y=H*.31,s=Math.min(W,H)/620;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#b4c1d0';ctx.fillRect(-70,-80,140,105);ctx.fillStyle='#9ba9b9';ctx.fillRect(-124,-47,248,72);ctx.fillStyle='#d7d2b5';for(let i=-2;i<=2;i++){ctx.fillRect(i*42-13,-138,26,58);ctx.beginPath();ctx.moveTo(i*42-18,-138);ctx.lineTo(i*42,-161);ctx.lineTo(i*42+18,-138);ctx.fill()}ctx.fillStyle='#77869c';ctx.fillRect(-62,-150,124,48);ctx.beginPath();ctx.moveTo(-62,-150);ctx.lineTo(0,-185);ctx.lineTo(62,-150);ctx.fill();ctx.fillStyle='#ffc86a';for(let i=-3;i<4;i+=2){ctx.beginPath();ctx.arc(i*27,-72,5,0,7);ctx.fill()}ctx.restore()}
function drawTerrain(){ctx.save();ctx.translate(0,0);ctx.globalAlpha=.35;ctx.fillStyle='#1d5961';ctx.beginPath();ctx.moveTo(0,H*.62);ctx.bezierCurveTo(W*.18,H*.52,W*.32,H*.75,W*.48,H*.61);ctx.bezierCurveTo(W*.65,H*.48,W*.74,H*.7,W,H*.57);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();ctx.globalAlpha=.7;ctx.strokeStyle='#91b6a6';ctx.lineWidth=1;for(let i=0;i<18;i++){let x=(i*137+parallax*70)%W,y=H*.68+(i*79)%H*.24;ctx.beginPath();ctx.arc(x,y,20+(i%4)*8,0,7);ctx.stroke()}ctx.restore();ctx.save();ctx.strokeStyle='rgba(163,210,199,.18)';ctx.lineWidth=1;for(let i=-10;i<12;i++){ctx.beginPath();ctx.moveTo(W*.5+i*70,H*.42);ctx.lineTo(W*.5+i*120,H);ctx.stroke()}ctx.restore()}
function drawAtmosphere(){ctx.save();ctx.globalCompositeOperation='screen';for(let i=0;i<18;i++){let x=(i*211+parallax*20)%W,y=90+(i*137)%Math.max(H*.52,1);ctx.fillStyle=i%3?'rgba(190,180,255,.12)':'rgba(255,220,155,.16)';ctx.beginPath();ctx.arc(x,y,1+(i%4),0,7);ctx.fill()}ctx.restore();ctx.save();ctx.globalAlpha=.09;ctx.fillStyle='#c5a4ff';for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse((i*310+parallax*50)% (W+300)-150,80+i*23,220,30,0,0,7);ctx.fill()}ctx.restore()}
function drawZone(){ctx.save();ctx.strokeStyle='rgba(166,109,255,.9)';ctx.lineWidth=3;ctx.setLineDash([12,8]);ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,7);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(151,91,234,.08)';ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,7);ctx.fill('evenodd');ctx.restore()}
function drawHero(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);ctx.fillStyle='#d4d7dd';ctx.beginPath();ctx.arc(0,0,player.r,0,7);ctx.fill();ctx.fillStyle='#69758d';ctx.fillRect(-8,-10,14,20);ctx.fillStyle='#69d8ff';ctx.beginPath();ctx.arc(5,0,5,0,7);ctx.fill();ctx.shadowBlur=14;ctx.shadowColor='#69d8ff';ctx.fillStyle='#b9f3ff';ctx.beginPath();ctx.arc(5,0,2.5,0,7);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#e7ae62';ctx.fillRect(8,-3,18,6);ctx.restore();ctx.save();ctx.translate(player.x,player.y);ctx.strokeStyle='rgba(123,226,255,.65)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,player.r+5,0,7);ctx.stroke();ctx.restore()}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle);ctx.fillStyle=e.frozen>0?'#74cfff':(e.flash>0?'#fff':'#6e4f82');ctx.beginPath();ctx.arc(0,0,e.r,0,7);ctx.fill();ctx.fillStyle=e.frozen>0?'#c8efff':'#b489be';ctx.fillRect(-5,-11,12,22);ctx.fillStyle='#ffc1a6';ctx.beginPath();ctx.arc(7,0,4,0,7);ctx.fill();ctx.strokeStyle='#f49e62';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-5,-9);ctx.lineTo(-15,-14);ctx.moveTo(-5,9);ctx.lineTo(-15,14);ctx.stroke();ctx.restore();ctx.fillStyle='#ff7e94';ctx.fillRect(e.x-12,e.y-e.r-9,24,3);ctx.fillStyle='#7dffba';ctx.fillRect(e.x-12,e.y-e.r-9,24*(e.hp/38),3)}
function drawPickup(p){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.spin);if(p.type==='relic'){ctx.shadowBlur=18;ctx.shadowColor='#ffd776';ctx.fillStyle='#ffd776';ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(9,-4);ctx.lineTo(5,10);ctx.lineTo(-5,10);ctx.lineTo(-9,-4);ctx.closePath();ctx.fill()}else{ctx.shadowBlur=15;ctx.shadowColor='#78ffc3';ctx.fillStyle='#75eab3';ctx.fillRect(-7,-7,14,14)}ctx.restore()}
function drawBolts(){ctx.save();ctx.globalCompositeOperation='lighter';ctx.lineCap='round';ctx.strokeStyle='#8deaff';ctx.lineWidth=3;for(let b of bolts){ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-b.vx*.025,b.y-b.vy*.025);ctx.stroke()}ctx.strokeStyle='#ff9f91';for(let b of enemyBolts){ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-b.vx*.03,b.y-b.vy*.03);ctx.stroke()}ctx.restore()}
function drawParticles(){ctx.save();ctx.globalCompositeOperation='lighter';for(let p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,7);ctx.fill()}ctx.restore()}
function drawMap(){mctx.clearRect(0,0,180,180);let g=mctx.createLinearGradient(0,0,180,180);g.addColorStop(0,'#52736d');g.addColorStop(1,'#263b4b');mctx.fillStyle=g;mctx.fillRect(0,0,180,180);mctx.fillStyle='#69755e';for(let i=0;i<5;i++){mctx.beginPath();mctx.ellipse(30+i*35,40+(i%2)*45,28,12,i*.5,0,7);mctx.fill()}mctx.strokeStyle='#a8c4b7';mctx.globalAlpha=.6;mctx.beginPath();mctx.arc(90,90,54,0,7);mctx.stroke();mctx.globalAlpha=1;mctx.fillStyle='#caffd7';let px=90+(player.x/W-.5)*145,py=90+(player.y/H-.5)*145;mctx.beginPath();mctx.moveTo(px,py-7);mctx.lineTo(px+5,py+5);mctx.lineTo(px-5,py+5);mctx.closePath();mctx.fill();mctx.fillStyle='#ffcf74';for(let p of pickups){let x=90+(p.x/W-.5)*145,y=90+(p.y/H-.5)*145;mctx.beginPath();mctx.arc(x,y,2,0,7);mctx.fill()}}
function render(){drawBackground();drawZone();for(let p of pickups)drawPickup(p);drawBolts();for(let e of enemies)drawEnemy(e);drawHero();drawParticles();drawMap();ctx.save();ctx.globalAlpha=.14;ctx.fillStyle='#8f70bd';for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(W*(.15+i*.35)+Math.sin(performance.now()/2300+i)*35,H*.18+i*20,90,18,0,0,7);ctx.fill()}ctx.restore();if(shake>1){ctx.setTransform(dpr,0,0,dpr,0,0)}}
function loop(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;update(dt);ctx.save();if(shake>1&&running){ctx.translate((Math.random-.5)*shake,(Math.random-.5)*shake)}render();ctx.restore();requestAnimationFrame(loop)}requestAnimationFrame(loop);

